if (db.products.length === 0) { db.products = starterProducts; fs.writeFileSync(DB_FILE, JSON.stringify(db, null, 2)); }
function save() { fs.writeFileSync(DB_FILE, JSON.stringify(db, null, 2)); }
function id(prefix='') { return prefix + crypto.randomBytes(5).toString('hex').toUpperCase(); }
function slugify(s) { return String(s || '').toLowerCase().trim().replace(/[^a-z0-9_-]/g, '').slice(0, 24); }
function safeUrl(raw) {
  if (!raw) return '';
  let s = String(raw).trim();
  if (!/^https?:\/\//i.test(s)) s = 'https://' + s;
  try { const u = new URL(s); return ['http:', 'https:'].includes(u.protocol) ? u.toString() : ''; } catch { return ''; }
}
function socialIcon(label, url) {
  const value = `${label || ''} ${url || ''}`.toLowerCase();
  if (value.includes('instagram')) return '◎';
  if (value.includes('linkedin')) return 'in';
  if (value.includes('whatsapp') || value.includes('wa.me')) return '◉';
  if (value.includes('youtube') || value.includes('youtu.be')) return '▶';
  if (value.includes('tiktok')) return '♪';
  if (value.includes('facebook') || value.includes('fb.com')) return 'f';
  if (value.includes('github')) return '⌘';
  if (value.includes('spotify')) return '♫';
  if (value.includes('telegram') || value.includes('t.me')) return '➤';
  if (value.includes('snapchat')) return '👻';
  if (value.includes('discord')) return '◈';
  if (value.includes('pinterest')) return 'P';
  if (value.includes('twitter') || value.includes('x.com')) return '𝕏';
  if (value.includes('website') || value.includes('portfolio')) return '↗';
  return '↗';
}
function profileFor(userId) { return db.profiles.find(p => p.userId === userId); }
function publicProfileUrl(req, username) { return `${req.protocol}://${req.get('host')}/u/${encodeURIComponent(username)}`; }
function hashActivationCode(code) { return crypto.createHash('sha256').update(String(code).trim().toUpperCase()).digest('hex'); }
function makeActivationCode() { return crypto.randomBytes(4).toString('hex').toUpperCase(); }
function claimTagForUser(code, userId) { const tag=db.tags.find(t=>t.code===code && t.active); if (!tag || tag.userId) return false; tag.userId=userId; tag.activatedAt=new Date().toISOString(); tag.activationHash=null; save(); return true; }

function currentUser(req) { return db.users.find(u => u.id === req.session.userId); }
function requireAuth(req, res, next) { if (!currentUser(req)) return res.redirect('/login'); next(); }
function requireAdmin(req, res, next) { const u = currentUser(req); if (!u || !u.isAdmin) return res.status(403).send(page('Access denied', '<div class="card"><h1>Admin only</h1><p>This area is for the Tagnet administrator.</p><a class="btn" href="/dashboard">Go to dashboard</a></div>')); next(); }

// Seed demo accounts locally. On hosted environments, require a custom admin account.
if (db.users.length === 0) {
  const adminEmail = process.env.NODE_ENV === 'production' ? String(process.env.ADMIN_EMAIL || '').trim().toLowerCase() : 'admin@tagnet.local';
  const adminPassword = process.env.NODE_ENV === 'production' ? String(process.env.ADMIN_PASSWORD || '') : 'TagnetAdmin123!';
  if (process.env.NODE_ENV === 'production' && (!adminEmail.includes('@') || adminPassword.length < 16)) {
    throw new Error('For production, set ADMIN_EMAIL and ADMIN_PASSWORD (at least 16 characters) before starting.');
  }
  const adminId = id('USR_');
  db.users.push({ id: adminId, email: adminEmail, passwordHash: bcrypt.hashSync(adminPassword, 12), isAdmin: true, createdAt: new Date().toISOString() });
  if (process.env.NODE_ENV !== 'production') {
    db.users.push({ id: 'USR_DEMO01', email: 'demo@tagnet.local', passwordHash: bcrypt.hashSync('DemoUser123!', 10), isAdmin: false, createdAt: new Date().toISOString() });
    db.profiles.push({ id: id('PRO_'), userId: 'USR_DEMO01', username: 'ziyan', name: 'Ziyan', bio: 'Building ideas. Connecting people.', avatar: '', theme: 'lilac', links: [{ label: 'Instagram', url: 'https://instagram.com/', icon: '◎' }, { label: 'LinkedIn', url: 'https://linkedin.com/', icon: 'in' }, { label: 'WhatsApp', url: 'https://wa.me/', icon: '◉' }] });
    db.tags.push({ id: id('TAG_'), code: 'TG000001', userId: 'USR_DEMO01', active: true, createdAt: new Date().toISOString() });
  }
  save();
}

app.set('trust proxy', 1);
app.use(express.urlencoded({ extended: true, limit: '1mb' }));
app.use(express.json({ limit: '1mb' }));
if (process.env.NODE_ENV === 'production' && !process.env.SESSION_SECRET) {
  throw new Error('Set a strong SESSION_SECRET environment variable before production deployment.');
}
app.use(session({ secret: process.env.SESSION_SECRET || 'replace-this-local-tagnet-secret-before-deploying', resave: false, saveUninitialized: false, cookie: { httpOnly: true, sameSite: 'lax', secure: process.env.NODE_ENV === 'production', maxAge: 1000 * 60 * 60 * 8 } }));
app.use('/static', express.static(path.join(__dirname, 'public')));
app.use('/uploads', express.static(UPLOAD_DIR));

function page(title, body, user=null) {
  const nav = user ? `<nav class="nav"><a class="brand" href="/">tagnet<span>.</span></a><div class="navlinks"><a href="/dashboard">Dashboard</a><a href="/products">Discover</a>${user.isAdmin ? '<a href="/admin">Admin</a>' : ''}<button class="theme-toggle" type="button" id="theme-toggle" aria-label="Toggle dark mode">☾ <span>Dark mode</span></button><form method="post" action="/logout"><button class="navbtn">Log out</button></form></div></nav>` : `<nav class="nav"><a class="brand" href="/">tagnet<span>.</span></a><div class="navlinks"><a href="/products">Discover</a><a href="/login">Log in</a><button class="theme-toggle" type="button" id="theme-toggle" aria-label="Toggle dark mode">☾ <span>Dark mode</span></button><a class="navcta" href="/signup">Get started ↗</a></div></nav>`;
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#f8f5ff"><title>${escapeHtml(title)} · Tagnet</title><link rel="stylesheet" href="/static/style.css"></head><body>${nav}<main class="main">${body}</main><footer class="footer">Made for better connections <span>✳</span> Tagnet MVP</footer><script>(function(){const root=document.documentElement;const saved=localStorage.getItem('tagnet-theme');if(saved==='dark')root.dataset.theme='dark';function update(){const dark=root.dataset.theme==='dark';const b=document.getElementById('theme-toggle');if(b){b.innerHTML=dark?'☀ <span>Light mode</span>':'☾ <span>Dark mode</span>';b.setAttribute('aria-pressed',String(dark));}}document.addEventListener('click',function(e){if(e.target.closest('#theme-toggle')){const dark=root.dataset.theme!=='dark';root.dataset.theme=dark?'dark':'light';localStorage.setItem('tagnet-theme',dark?'dark':'light');update();}const copy=e.target.closest('[data-copy]');if(copy){const value=copy.getAttribute('data-copy');navigator.clipboard.writeText(value).then(()=>{const old=copy.textContent;copy.textContent='Copied ✓';setTimeout(()=>copy.textContent=old,1200)}).catch(()=>prompt('Copy this value',value));}});update();})();</script></body></html>`;
}
function escapeHtml(v='') { return String(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function layoutForm(title, subtitle, inner, user=null) { return page(title, `<section class="auth-wrap"><div class="eyebrow">TAGNET · DIGITAL IDENTITY</div><h1>${title}</h1><p class="muted">${subtitle}</p><div class="card">${inner}</div></section>`, user); }

app.get('/', (req, res) => {
  const user = currentUser(req);
  res.send(page('Tap into your identity', `<section class="hero"><div class="hero-copy"><div class="pill"><span class="dot"></span> YOUR WORLD, ONE TAP AWAY</div><h1>Small keychain.<br><em>Big connection.</em></h1><p class="lead">One tap opens your digital identity. Keep your socials in one clean, shareable profile — powered by Tagnet.</p><div class="hero-actions"><a class="btn" href="${user ? '/dashboard' : '/signup'}">${user ? 'Open dashboard' : 'Create your profile'} <span>↗</span></a><a class="text-link" href="/u/ziyan">View demo profile →</a></div><div class="trust-row"><span>✳ NFC-ready</span><span>✳ Shareable profile</span><span>✳ Update anytime</span></div></div><div class="hero-art"><div class="orb orb-one"></div><div class="orb orb-two"></div><div class="product-card"><div class="product-top"><span class="tiny-logo">t.</span><span class="chip-label">TAP TO CONNECT</span></div><div class="keychain"><div class="ring"></div><div class="tag-face"><div class="tag-logo">t<span>.</span></div><div class="tag-line"></div><div class="tag-caption">YOUR DIGITAL WORLD</div></div></div><div class="product-bottom"><span>TAGNET NFC</span><span>01 / 100</span></div></div><div class="floating-note note-top">✦ Your links, together</div><div class="floating-note note-bottom"><span class="green-dot"></span> Profile is live</div></div></section><section class="feature-grid"><article><div class="feature-icon">↗</div><h3>One link for everything</h3><p>Bring your socials and contact links into one place.</p></article><article><div class="feature-icon">⌁</div><h3>Tap. Connect. Done.</h3><p>A compatible phone can open your profile with an NFC tap.</p></article><article><div class="feature-icon">✎</div><h3>Always up to date</h3><p>Change links in your dashboard without reprogramming the tag.</p></article></section>`, user));
});

app.get('/signup', (req,res) => { const pending=req.session.pendingTagCode; res.send(layoutForm('Create your Tagnet', pending?`Create your account to activate NFC tag ${escapeHtml(pending)}.`:'Set up your account and claim a profile username.', `<form method="post" action="/signup" class="form"><label>Email address</label><input name="email" type="email" required maxlength="160" placeholder="you@example.com"><label>Password</label><input name="password" type="password" required minlength="8" placeholder="At least 8 characters"><label>Profile username</label><div class="username-input"><span>/u/</span><input name="username" required pattern="[A-Za-z0-9_-]{3,24}" minlength="3" maxlength="24" placeholder="yourname"></div><button class="btn full" type="submit">Create account${pending?' & activate tag':' '} ↗</button></form><p class="form-foot">Already have an account? <a href="/login">Log in</a></p>`, currentUser(req))); });
app.post('/signup', async (req,res) => {
  const email = String(req.body.email||'').trim().toLowerCase(); const password = String(req.body.password||''); const username = slugify(req.body.username);
  if (!email.includes('@') || password.length < 8 || username.length < 3) return res.status(400).send(layoutForm('Almost there', 'Check your details and try again.', `<p class="error">Use a valid email, password with 8+ characters, and username with 3–24 letters/numbers.</p><a href="/signup">Go back</a>`));
  if (db.users.some(u=>u.email===email)) return res.status(409).send(layoutForm('Email already used', 'Try logging in instead.', `<p class="error">An account with this email already exists.</p><a href="/login">Log in</a>`));
  if (db.profiles.some(p=>p.username===username)) return res.status(409).send(layoutForm('Username taken', 'Choose another username.', `<p class="error">That profile URL is already in use.</p><a href="/signup">Try again</a>`));
  const user = { id:id('USR_'), email, passwordHash: await bcrypt.hash(password,10), isAdmin:false, createdAt:new Date().toISOString() };
  db.users.push(user); db.profiles.push({ id:id('PRO_'), userId:user.id, username, name:username, bio:'Add a little about yourself.', avatar:'', theme:'lilac', links:[] }); if(req.session.pendingTagCode){ claimTagForUser(req.session.pendingTagCode,user.id); delete req.session.pendingTagCode; } save(); req.session.userId=user.id; res.redirect('/dashboard');
});
app.get('/login', (req,res) => { const pending=req.session.pendingTagCode; res.send(layoutForm('Welcome back', pending?`Log in to activate NFC tag ${escapeHtml(pending)}.`:'Your digital identity is waiting.', `<form method="post" action="/login" class="form"><label>Email address</label><input name="email" type="email" required placeholder="you@example.com"><label>Password</label><input name="password" type="password" required placeholder="Your password"><button class="btn full" type="submit">Log in${pending?' & activate tag':' '} ↗</button></form><p class="form-foot">New to Tagnet? <a href="/signup">Create an account</a></p>`, currentUser(req))); });
app.post('/login', async (req,res) => { const email=String(req.body.email||'').trim().toLowerCase(); const user=db.users.find(u=>u.email===email); if (!user || !(await bcrypt.compare(String(req.body.password||''),user.passwordHash))) return res.status(401).send(layoutForm('Could not log in', 'The email or password was incorrect.', `<p class="error">Please check your credentials and try again.</p><a href="/login">Try again</a>`)); if(req.session.pendingTagCode && !user.isAdmin){ claimTagForUser(req.session.pendingTagCode,user.id); delete req.session.pendingTagCode; } req.session.userId=user.id; res.redirect(user.isAdmin?'/admin':'/dashboard'); });
app.post('/logout', (req,res)=>req.session.destroy(()=>res.redirect('/')));

app.get('/dashboard', requireAuth, (req,res) => {
  const user=currentUser(req); if (user.isAdmin) return res.redirect('/admin'); let p=profileFor(user.id); if (!p) { p={ id:id('PRO_'), userId:user.id, username:'user'+user.id.slice(-6).toLowerCase(), name:'Your name', bio:'Add a little about yourself.', avatar:'', theme:'lilac', links:[] }; db.profiles.push(p); save(); } const tags=db.tags.filter(t=>t.userId===user.id); const featuredProducts=['Students','Creators','Professionals'].map(a=>db.products.find(x=>x.audience===a)).filter(Boolean);
  const links=p.links.map((l,i)=>`<div class="link-row"><span class="link-number social-icon">${escapeHtml(socialIcon(l.label,l.url))}</span><div class="link-fields"><input form="profile-form" name="linkLabel${i}" value="${escapeHtml(l.label)}" aria-label="Link label ${i+1}"><input form="profile-form" name="linkUrl${i}" value="${escapeHtml(l.url)}" aria-label="Link URL ${i+1}"></div><label class="check-label"><input form="profile-form" type="checkbox" name="removeLink${i}"> Remove</label></div>`).join('');
  const tagHtml=tags.length?tags.map(t=>`<div class="tag-row"><div><strong>${escapeHtml(t.code)}</strong><small>${t.active?'Active':'Disabled'} · <a href="/t/${encodeURIComponent(t.code)}" target="_blank">Test tap URL ↗</a></small></div><span class="tag-status ${t.active?'':'inactive'}">${t.active?'● Active':'○ Disabled'}</span></div>`).join(''):'<p class="muted">No NFC tag assigned yet. Ask the Tagnet admin to assign one.</p>';
  const body=`<div class="page-heading"><div><div class="eyebrow">YOUR SPACE</div><h1>Dashboard<span class="period">.</span></h1><p class="muted">Manage your public profile and the links you share.</p></div><div class="dashboard-heading-actions"><a class="small-btn" href="/my-orders">My orders (${db.orders.filter(o=>o.email===user.email).length})</a><a class="btn" target="_blank" href="/u/${encodeURIComponent(p.username)}">View profile ↗</a></div></div><div class="dashboard-grid"><section class="panel editor-panel"><div class="panel-heading"><div><h2>Profile details</h2><p>These details appear on your public page.</p></div><span class="step-badge">01</span></div><form id="profile-form" class="form" method="post" enctype="multipart/form-data" action="/dashboard/profile"><label>Display name</label><input name="name" required maxlength="60" value="${escapeHtml(p.name)}"><label>Username / public URL</label><div class="username-input"><span>tagnet.local/u/</span><input name="username" required pattern="[A-Za-z0-9_-]{3,24}" minlength="3" maxlength="24" value="${escapeHtml(p.username)}"></div><label>Short bio</label><textarea name="bio" maxlength="180" rows="3" placeholder="What should people know about you?">${escapeHtml(p.bio)}</textarea><label>Upload profile photo <span class="optional">(JPG, PNG, WEBP, GIF · max 5 MB)</span></label><input name="avatarFile" type="file" accept="image/png,image/jpeg,image/webp,image/gif"><label>Or use profile photo URL <span class="optional">(optional)</span></label><input name="avatar" type="url" value="${escapeHtml(p.avatar.startsWith('/uploads/')?'':p.avatar)}" placeholder="https://..."><label>Profession / category</label><select name="category">${['General','Creator','Designer','Developer','Professional','Entrepreneur','Gamer','Medical','Student','Commerce','Engineer'].map(c=>`<option value="${c}" ${(p.category||'General')===c?'selected':''}>${c}</option>`).join('')}</select><label>Profile design</label><select name="theme">${[['liquid','Liquid Glass'],['glass','Glassmorphism'],['neo','Neomorphism'],['glow','Glow Effects'],['depth','Shadows & Depth'],['minimal','Minimalist'],['maximal','Maximalism'],['neumorphic','Neumorphism'],['clay','Claymorphism'],['brutal','Brutalism'],['neo-brutal','Neo-Brutalism'],['skeuo','Skeuomorphism'],['flat','Flat Design'],['material','Material Design'],['bento','Bento UI'],['y2k','Y2K Design'],['cyberpunk','Cyberpunk'],['editorial','Editorial Design'],['elevation','Dark Mode Elevation'],['soft3d','3D Soft Realism'],['spatial','Spatial UI'],['gold','Midnight Gold'],['developer','Developer Grid'],['gamer','Neon Gamer'],['medical','Medical Sage'],['botanical','Botanical Calm'],['bold','Bold Contrast'],['lilac','Soft Lilac'],['peach','Peach'],['mint','Mint'],['dark','Midnight']].map(([v,l])=>`<option value="${v}" ${p.theme===v?'selected':''}>${l}</option>`).join('')}</select><div class="panel-heading links-title"><div><h2>Social links</h2><p>Edit existing links or add new ones below.</p></div><span class="step-badge">02</span></div>${links || '<p class="muted">No links added yet — add your first link below.</p>'}<div class="new-link"><label>Add another link</label><div class="two-col"><input name="newLinkLabel" maxlength="40" placeholder="Instagram, LinkedIn..."><input name="newLinkUrl" placeholder="https://... "></div></div><button class="btn full" type="submit">Save profile changes ✓</button></form></section><aside class="side-stack"><section class="panel preview-panel"><div class="panel-heading"><div><h2>Live profile</h2><p>Your public identity at a glance.</p></div><span class="step-badge">↗</span></div><div class="mini-profile theme-${escapeHtml(p.theme)}"><div class="mini-avatar">${p.avatar?`<img src="${escapeHtml(p.avatar)}" alt="">`:escapeHtml((p.name||'?').charAt(0).toUpperCase())}</div><h3>${escapeHtml(p.name)}</h3><p>@${escapeHtml(p.username)}</p><div class="mini-bio">${escapeHtml(p.bio)}</div><div class="mini-link-count">${p.links.length} SOCIAL LINKS</div></div><a class="text-link" target="_blank" href="/u/${encodeURIComponent(p.username)}">Open full profile →</a></section><section class="panel"><div class="panel-heading"><div><h2>Your NFC tags</h2><p>Tags assigned to your account.</p></div><span class="step-badge">03</span></div>${tagHtml}</section><section class="panel qr-panel"><div class="panel-heading"><div><h2>Your profile QR</h2><p>Download and print it on your keychain packaging.</p></div><span class="step-badge">QR</span></div><div class="qr-preview"><img src="/u/${encodeURIComponent(p.username)}/qr.png" alt="QR code for ${escapeHtml(p.name)} profile"></div><p class="muted qr-url">${escapeHtml(`/u/${p.username}`)}</p><a class="btn full" href="/u/${encodeURIComponent(p.username)}/qr.png?download=1">Download QR PNG ↓</a><p class="tiny-note">QR opens your public profile. Print test at actual keychain size before bulk printing.</p></section><section class="tip-card"><span>✦ QUICK TIP</span><p>Program the NFC chip with your Tagnet tap URL — not a social media URL. Then you can update your profile without reprogramming the chip.</p></section></aside></div><section class="catalog-section"><div class="catalog-heading"><div><div class="eyebrow">CURATED FOR YOUR GOALS</div><h2>Explore products<span class="period">.</span></h2><p class="muted">Student, creator aur professional life ke liye useful picks.</p></div><a class="text-link" href="/products">View all products →</a></div><div class="product-grid">${featuredProducts.map(productCard).join('')}</div></section>`;
  res.send(page('Dashboard',body,user));
});
app.post('/dashboard/profile', requireAuth, upload.single('avatarFile'), (req,res) => {
  const user=currentUser(req), p=profileFor(user.id); if(!p) return res.status(404).send('Profile not found');
  const username=slugify(req.body.username); if(username.length<3) return res.status(400).send('Username must be 3–24 characters.');
  if(db.profiles.some(x=>x.username===username && x.userId!==user.id)) return res.status(409).send('Username already exists. Go back and choose another.');
  p.username=username; p.name=String(req.body.name||'').trim().slice(0,60)||username; p.bio=String(req.body.bio||'').trim().slice(0,180); if (req.file) p.avatar=`/uploads/${req.file.filename}`; else if (String(req.body.avatar||'').trim()) p.avatar=safeUrl(req.body.avatar); p.theme=['lilac','peach','mint','dark','editorial','gold','developer','gamer','medical','botanical','glass','bold'].includes(req.body.theme)?req.body.theme:'lilac'; p.category=['General','Creator','Designer','Developer','Professional','Entrepreneur','Gamer','Medical','Student','Commerce','Engineer'].includes(req.body.category)?req.body.category:'General';
  const links=[]; const old=profileFor(user.id).links;
  for(let i=0;i<old.length;i++){ if(req.body['removeLink'+i]) continue; const label=String(req.body['linkLabel'+i]||'').trim().slice(0,40); const url=safeUrl(req.body['linkUrl'+i]); if(label&&url) links.push({label,url,icon:socialIcon(label,url)}); }
  const newLabel=String(req.body.newLinkLabel||'').trim().slice(0,40), newUrl=safeUrl(req.body.newLinkUrl); if(newLabel&&newUrl) links.push({label:newLabel,url:newUrl,icon:socialIcon(newLabel,newUrl)}); p.links=links.slice(0,20); save(); res.redirect('/dashboard?saved=1');
});

function productCard(p) {
 return `<article class="product-card-item"><a class="product-image" href="/products/${encodeURIComponent(p.id)}"><img src="${escapeHtml(p.image)}" alt="${escapeHtml(p.title)}" loading="lazy" onerror="this.style.display='none'"><span class="product-audience">${escapeHtml(p.audience)}</span></a><div class="product-info"><div class="product-category">${escapeHtml(p.category)}</div><h3>${escapeHtml(p.title)}</h3><p>${escapeHtml(p.description)}</p><div class="product-meta"><strong>₹${Number(p.price).toLocaleString('en-IN')}</strong><span>${escapeHtml(p.details||'Curated pick')}</span></div><a class="btn product-btn" href="/products/${encodeURIComponent(p.id)}">View details & buy ↗</a></div></article>`;
}
app.get('/products', (req,res) => {
 const audience=String(req.query.audience||'').trim(); const category=String(req.query.category||'').trim();
 const filtered=db.products.filter(p=>(!audience||p.audience===audience)&&(!category||p.category===category));
 const audiences=['Students','Creators','Professionals'];
 const categories=[...new Set(db.products.map(p=>p.category))].sort();
 const body=`<div class="page-heading"><div><div class="eyebrow">TAGNET PICKS</div><h1>Find your fit<span class="period">.</span></h1><p class="muted">Apni study, creator workflow ya profession ke hisaab se curated products dekho.</p></div></div><section class="panel filter-panel"><form class="filter-form" method="get" action="/products"><label>I'm looking for<select name="audience"><option value="">All audiences</option>${audiences.map(a=>`<option value="${escapeHtml(a)}" ${audience===a?'selected':''}>${escapeHtml(a)}</option>`).join('')}</select></label><label>Category<select name="category"><option value="">All categories</option>${categories.map(c=>`<option value="${escapeHtml(c)}" ${category===c?'selected':''}>${escapeHtml(c)}</option>`).join('')}</select></label><button class="btn" type="submit">Apply filters</button><a class="text-link" href="/products">Reset</a></form><div class="category-chips">${audiences.map(a=>`<a class="category-chip ${audience===a?'selected':''}" href="/products?audience=${encodeURIComponent(a)}">${escapeHtml(a)}</a>`).join('')}</div></section><div class="catalog-results"><div class="results-label">${filtered.length} curated ${filtered.length===1?'item':'items'}</div><div class="product-grid">${filtered.map(productCard).join('')||'<div class="empty-catalog">No products in this filter yet. Try another category.</div>'}</div></div>`;
 res.send(page('Discover products',body,currentUser(req)));
});

app.get('/u/:username/qr.png', async (req,res) => {
  const p=db.profiles.find(x=>x.username.toLowerCase()===String(req.params.username).toLowerCase());
  if(!p) return res.status(404).send('Profile not found');
  try {
    const target=publicProfileUrl(req,p.username);
    const png=await QRCode.toBuffer(target,{type:'png',errorCorrectionLevel:'H',margin:2,width:1000,color:{dark:'#111111',light:'#FFFFFF'}});
    res.setHeader('Content-Type','image/png');
    res.setHeader('Cache-Control','no-store');
    if(req.query.download==='1') res.setHeader('Content-Disposition',`attachment; filename="tagnet-${p.username}-qr.png"`);
    res.send(png);
  } catch { res.status(500).send('Could not generate QR code'); }
});

app.get('/u/:username', (req,res) => {
  const p=db.profiles.find(x=>x.username.toLowerCase()===String(req.params.username).toLowerCase()); if(!p) return res.status(404).send(page('Profile not found',`<div class="not-found"><div class="eyebrow">404 · PROFILE NOT FOUND</div><h1>This link is taking a break.</h1><p class="muted">The username may have changed, or the profile does not exist yet.</p><a class="btn" href="/">Back to Tagnet</a></div>`));
  const user=db.users.find(u=>u.id===p.userId); db.profileViews.push({username:p.username,at:new Date().toISOString()}); if(db.profileViews.length>20000) db.profileViews=db.profileViews.slice(-20000); save(); const body=`<section class="public-wrap theme-${escapeHtml(p.theme)} category-${escapeHtml(p.category||'General').toLowerCase()}"><a class="public-brand" href="/">tagnet<span>.</span></a><div class="public-card"><div class="public-avatar">${p.avatar?`<img src="${escapeHtml(p.avatar)}" alt="${escapeHtml(p.name)}">`:escapeHtml((p.name||'?').charAt(0).toUpperCase())}</div><div class="public-kicker">DIGITAL IDENTITY</div><h1>${escapeHtml(p.name)}</h1><div class="handle">@${escapeHtml(p.username)}</div><p class="public-bio">${escapeHtml(p.bio)}</p><div class="public-links">${p.links.map((l,i)=>`<a class="social-link" href="${escapeHtml(l.url)}" target="_blank" rel="noopener noreferrer"><span class="social-icon">${escapeHtml(socialIcon(l.label,l.url))}</span><span>${escapeHtml(l.label)}</span><span class="link-arrow">↗</span></a>`).join('') || '<div class="empty-links">Social links coming soon.</div>'}</div><button class="share-button" onclick="navigator.clipboard.writeText(location.href).then(()=>{this.textContent='Link copied ✓'}).catch(()=>{prompt('Copy your profile link',location.href)})">Share profile ↗</button></div><div class="public-footer">POWERED BY <strong>TAGNET.</strong><span>One tap. More connection.</span></div></section>`;
  res.send(page(`${p.name} (@${p.username})`,body));
});
app.get('/t/:code', (req,res) => { const tag=db.tags.find(t=>t.code.toLowerCase()===String(req.params.code).toLowerCase() && t.active); if(!tag) return res.status(404).send(page('Tag not active',`<div class="not-found"><h1>This Tagnet tag isn't active.</h1><p class="muted">Check the tag code or contact Tagnet support.</p><a class="btn" href="/">Go to Tagnet</a></div>`,currentUser(req))); if(tag.userId){ const p=profileFor(tag.userId); if(!p) return res.status(404).send(page('Profile not assigned','<div class="not-found"><h1>Profile setup is incomplete.</h1></div>',currentUser(req))); return res.redirect(302,`/u/${encodeURIComponent(p.username)}`); } const body=`<section class="activation-wrap"><div class="activation-icon">⌁</div><div class="eyebrow">TAGNET NFC ACTIVATION</div><h1>Your keychain.<br><em>Your identity.</em></h1><p class="muted">Tag ID: <strong>${escapeHtml(tag.code)}</strong>. Enter the one-time activation code included in your package. You only need your phone browser—no NFC app required.</p><form class="form activation-form" method="post" action="/t/${encodeURIComponent(tag.code)}/activate"><label>Activation code</label><input name="activationCode" required minlength="8" maxlength="8" pattern="[A-Fa-f0-9]{8}" placeholder="8-character code" autocomplete="one-time-code"><button class="btn full" type="submit">Verify & continue ↗</button></form><p class="muted activation-note">Lost your activation card? Contact Tagnet support before claiming this tag.</p></section>`; res.send(page('Activate your keychain',body,currentUser(req))); });
app.post('/t/:code/activate', (req,res) => { const code=String(req.params.code||'').toUpperCase(); const tag=db.tags.find(t=>t.code===code && t.active); if(!tag) return res.status(404).send(page('Tag not found','<div class="not-found"><h1>This tag is not available.</h1></div>',currentUser(req))); if(tag.userId){ const p=profileFor(tag.userId); return p?res.redirect(`/u/${encodeURIComponent(p.username)}`):res.status(409).send(page('Already activated','<div class="not-found"><h1>This tag has already been activated.</h1></div>',currentUser(req))); } const supplied=hashActivationCode(req.body.activationCode||''); const expected=tag.activationHash||''; const valid=expected.length===supplied.length && expected.length>0 && crypto.timingSafeEqual(Buffer.from(expected),Buffer.from(supplied)); if(!valid) return res.status(400).send(page('Activation code incorrect',`<section class="auth-wrap"><h1>Code didn’t match.</h1><p class="muted">Check the 8-character code printed on the activation card and try again.</p><a class="btn" href="/t/${encodeURIComponent(tag.code)}">Try again</a></section>`,currentUser(req))); const user=currentUser(req); if(user){ if(user.isAdmin) return res.status(403).send(page('Customer account required','<div class="not-found"><h1>Log out of admin and use a customer account to activate this tag.</h1></div>',user)); claimTagForUser(tag.code,user.id); return res.redirect('/dashboard?activated='+encodeURIComponent(tag.code)); } req.session.pendingTagCode=tag.code; res.redirect('/signup'); });

app.get('/admin', requireAuth, requireAdmin, (req,res) => {
  const user=currentUser(req); const customers=db.users.filter(u=>!u.isAdmin); const tags=db.tags; const tagNotice=req.session.newTagNotice; delete req.session.newTagNotice;
  const customerRows=customers.map(c=>{const p=profileFor(c.id); const tag=tags.find(t=>t.userId===c.id); return `<tr><td><strong>${escapeHtml(c.email)}</strong><small>${p?'@'+escapeHtml(p.username):'No profile'}</small></td><td>${p?escapeHtml(p.name):'—'}</td><td>${tag?escapeHtml(tag.code):'<span class="muted">Not assigned</span>'}</td><td>${p?`<a href="/u/${encodeURIComponent(p.username)}" target="_blank">View ↗</a>`:'—'}</td></tr>`;}).join('');
  const tagRows=tags.map(t=>{const p=profileFor(t.userId); return `<tr><td><strong>${escapeHtml(t.code)}</strong></td><td>${p?escapeHtml(p.username):'Unassigned'}</td><td><span class="tag-status ${t.active?'':'inactive'}">${t.active?'Active':'Disabled'}</span></td><td><form class="inline-form" method="post" action="/admin/tags/toggle"><input type="hidden" name="code" value="${escapeHtml(t.code)}"><button class="small-btn" type="submit">${t.active?'Disable':'Enable'}</button></form></td></tr>`;}).join('');
  const body=`<div class="page-heading"><div><div class="eyebrow">CONTROL CENTER</div><h1>Admin panel<span class="period">.</span></h1><p class="muted">Manage customer profiles and NFC tag assignments.</p></div><span class="admin-pill">ADMIN ACCESS</span><a class="text-link" href="/admin/tag-lookup">NFC tag lookup ↗</a></div>${tagNotice?`<section class="panel activation-notice"><div class="panel-heading"><div><h2>New tag ready — save this activation code</h2><p>Shown only once. Put the code in the customer’s package.</p></div><span class="step-badge">✓</span></div><div class="activation-code-box"><span>Tag ID</span><strong>${escapeHtml(tagNotice.code)}</strong><button type="button" class="small-btn copy-value" data-copy="${escapeHtml(tagNotice.code)}">Copy ID</button></div><div class="activation-code-box"><span>Activation code</span><strong>${escapeHtml(tagNotice.activationCode)}</strong><button type="button" class="small-btn copy-value" data-copy="${escapeHtml(tagNotice.activationCode)}">Copy code</button></div><label>NFC URL to write to the chip</label><div class="copy-url-row"><input readonly value="${escapeHtml(tagNotice.url)}"><button type="button" class="small-btn copy-value" data-copy="${escapeHtml(tagNotice.url)}">Copy URL</button></div><p class="muted small-note">Write only the NFC URL to the chip. Print the activation code separately on a small card; never write the activation code to NFC.</p></section>`:''}<div class="stats-grid"><div class="stat-card"><span>Customers</span><strong>${customers.length}</strong><small>Registered accounts</small></div><div class="stat-card"><span>NFC tags</span><strong>${tags.length}</strong><small>Created tag records</small></div><div class="stat-card"><span>Assigned tags</span><strong>${tags.filter(t=>t.userId).length}</strong><small>Linked to customers</small></div></div><div class="admin-grid"><section class="panel"><div class="panel-heading"><div><h2>Prepare a new NFC keychain</h2><p>Create a tag ID and one-time activation code for the package.</p></div></div><form class="form" method="post" action="/admin/tags"><label>Optional tag code</label><input name="code" placeholder="Leave blank to auto-generate" maxlength="40"><button class="btn full" type="submit">Generate tag + activation code</button></form><p class="muted small-note">Do not assign the customer here. Customer claims the tag after delivery.</p></section></div><section class="panel table-panel"><div class="panel-heading"><div><h2>Customers</h2><p>Accounts and linked tag details.</p></div></div><div class="table-scroll"><table><thead><tr><th>Account</th><th>Name</th><th>Tag code</th><th>Profile</th></tr></thead><tbody>${customerRows||'<tr><td colspan="4">No customers yet.</td></tr>'}</tbody></table></div></section><section class="panel table-panel"><div class="panel-heading"><div><h2>Complete customer data</h2><p>Admin-only view of registered account details, public profile fields, social links, tag assignment and QR download. Passwords are never shown.</p></div></div><div class="customer-detail-grid compact-customer-grid">${customers.map(c=>{const p=profileFor(c.id);const userTags=tags.filter(t=>t.userId===c.id);return `<article class="customer-detail-card"><div class="customer-detail-top"><div class="mini-avatar">${p&&p.avatar?`<img src="${escapeHtml(p.avatar)}" alt="">`:escapeHtml((p&&p.name||c.email).charAt(0).toUpperCase())}</div><div><h3>${escapeHtml(p?p.name:'Profile not set')}</h3><p>${escapeHtml(c.email)}</p><small>Joined ${escapeHtml(new Date(c.createdAt).toLocaleString())}</small></div></div><dl class="customer-data-list"><dt>User ID</dt><dd>${escapeHtml(c.id)}</dd><dt>Username</dt><dd>${p?`@${escapeHtml(p.username)}`:'—'}</dd><dt>Bio</dt><dd>${p?escapeHtml(p.bio||'—'):'—'}</dd><dt>Theme</dt><dd>${p?escapeHtml(p.theme||'lilac'):'—'}</dd><dt>Social links</dt><dd>${p&&p.links.length?p.links.map(l=>`<div class="admin-social-row"><span class="social-icon">${escapeHtml(socialIcon(l.label,l.url))}</span><span>${escapeHtml(l.label)}</span><a href="${escapeHtml(l.url)}" target="_blank" rel="noopener noreferrer">Open ↗</a></div>`).join(''):'No social links'}</dd><dt>NFC tags</dt><dd>${userTags.length?userTags.map(t=>`<div>${escapeHtml(t.code)} · ${t.active?'Active':'Disabled'}</div>`).join(''):'No tag assigned'}</dd></dl><div class="customer-detail-actions">${p?`<a class="btn" href="/u/${encodeURIComponent(p.username)}" target="_blank">View profile ↗</a><a class="small-btn" href="/u/${encodeURIComponent(p.username)}/qr.png?download=1">Download QR</a>`:''}<form method="post" action="/admin/users/delete" onsubmit="return confirm('Delete this customer and linked profile/tag data?')"><input type="hidden" name="userId" value="${escapeHtml(c.id)}"><button class="small-btn danger-btn" type="submit">Delete customer</button></form></div></article>`;}).join('')||'<p class="muted">No customer accounts yet.</p>'}</div></section><section class="panel table-panel"><div class="panel-heading"><div><h2>All NFC tags</h2><p>Enable or disable tag routing.</p></div></div><div class="table-scroll"><table><thead><tr><th>Code</th><th>Assigned profile</th><th>Status</th><th>Action</th></tr></thead><tbody>${tagRows||'<tr><td colspan="4">No tags yet.</td></tr>'}</tbody></table></div></section><section class="panel table-panel analytics-panel"><div class="panel-heading"><div><h2>Store analytics</h2><p>Live totals calculated from saved catalog, orders and recorded profile visits.</p></div></div><div class="analytics-kpis"><div><span>Products</span><strong>${db.products.length}</strong></div><div><span>Total orders</span><strong>${db.orders.length}</strong></div><div><span>Open orders</span><strong>${db.orders.filter(o=>!['Completed','Cancelled'].includes(o.status)).length}</strong></div><div><span>Completed sales</span><strong>₹${db.orders.filter(o=>o.status==='Completed').reduce((sum,o)=>sum+Number(o.total||0),0).toLocaleString('en-IN')}</strong></div><div><span>Profile views</span><strong>${db.profileViews.length}</strong></div></div><div class="analytics-grid"><div class="chart-card"><h3>Products by audience</h3><div class="donut-chart" style="--students:${db.products.filter(p=>p.audience==='Students').length};--creators:${db.products.filter(p=>p.audience==='Creators').length};--professionals:${db.products.filter(p=>p.audience==='Professionals').length};--total:${Math.max(1,db.products.length)}"><span>${db.products.length}<small>products</small></span></div><div class="chart-legend"><span>● Students (${db.products.filter(p=>p.audience==='Students').length})</span><span>● Creators (${db.products.filter(p=>p.audience==='Creators').length})</span><span>● Professionals (${db.products.filter(p=>p.audience==='Professionals').length})</span></div></div><div class="chart-card"><h3>Most viewed profiles</h3><div class="view-ranking">${db.profiles.map(p=>({p,count:db.profileViews.filter(v=>v.username===p.username).length})).sort((a,b)=>b.count-a.count).slice(0,8).map(x=>`<div><span>@${escapeHtml(x.p.username)}</span><strong>${x.count} views</strong></div>`).join('')||'<p class="muted">Views appear after public profiles are visited.</p>'}</div><p class="tiny-note">Counts are recorded profile-view events, not unique visitors.</p></div><div class="chart-card"><h3>Orders by status</h3><div class="view-ranking">${['New','Contacted','Confirmed','Shipped','Completed','Cancelled'].map(st=>`<div><span>${st}</span><strong>${db.orders.filter(o=>o.status===st).length}</strong></div>`).join('')}</div><p class="tiny-note">Completed sales count only orders marked Completed. Cancelled orders are excluded.</p></div></div></section><section class="panel table-panel"><div class="panel-heading"><div><h2>Add a product</h2><p>Product catalog mein new listing add karo. Audience aur sub-category alag choose karo.</p></div><span class="step-badge">＋</span></div><form class="form product-admin-form" method="post" enctype="multipart/form-data" action="/admin/products"><div class="two-col"><div><label>Product name</label><input name="title" required maxlength="100" placeholder="e.g. B.Com Study Planner"></div><div><label>Price (₹)</label><input name="price" type="number" min="0" max="1000000" required placeholder="499"></div></div><div class="two-col"><div><label>Main audience</label><select name="audience" required><option>Students</option><option>Creators</option><option>Professionals</option></select></div><div><label>Category / profession</label><input name="category" required maxlength="80" placeholder="CS & IT Students, YouTubers, Doctors..."></div></div><label>Description</label><textarea name="description" required maxlength="500" rows="3" placeholder="Product kya karta hai aur kis kaam aayega?"></textarea><label>Upload product image <span class="optional">(JPG, PNG, WEBP, GIF · max 5 MB)</span></label><input name="imageFile" type="file" accept="image/png,image/jpeg,image/webp,image/gif"><label>Or image URL</label><input name="image" type="url" placeholder="https://...image.jpg"><label>Product / buy URL <span class="optional">(optional)</span></label><input name="url" type="url" placeholder="https://... "><label>Extra details</label><input name="details" maxlength="180" placeholder="Digital download · Beginner friendly"><button class="btn" type="submit">Add product to catalog +</button></form></section><section class="panel table-panel"><div class="panel-heading"><div><h2>Current catalog (${db.products.length})</h2><p>These listings appear on Discover and the dashboard.</p></div><a class="text-link" href="/products" target="_blank">Preview catalog ↗</a></div><div class="table-scroll"><table><thead><tr><th>Product</th><th>Audience</th><th>Category</th><th>Price</th><th>Action</th></tr></thead><tbody>${db.products.map(p=>`<tr><td>${escapeHtml(p.title)}</td><td>${escapeHtml(p.audience)}</td><td>${escapeHtml(p.category)}</td><td>₹${Number(p.price).toLocaleString('en-IN')}</td><td><form method="post" action="/admin/products/delete" onsubmit="return confirm('Delete this product?')"><input type="hidden" name="productId" value="${escapeHtml(p.id)}"><button class="small-btn danger-btn">Delete</button></form></td></tr>`).join('')}</tbody></table></div></section>`;
  const ordersSection=`<section id="orders" class="panel table-panel"><div class="panel-heading"><div><h2>Order requests</h2><p>Delivery/contact details submitted by customers. Status updates appear in order tracking.</p></div><a class="text-link" href="/track-order" target="_blank">Open tracking page ↗</a></div><div class="table-scroll"><table><thead><tr><th>Order</th><th>Customer / delivery</th><th>Product</th><th>Total</th><th>Status</th><th>Actions</th></tr></thead><tbody>${db.orders.map(o=>`<tr><td><strong>${escapeHtml(o.id)}</strong><small>${new Date(o.createdAt).toLocaleString('en-IN')}</small><a href="/track-order?id=${encodeURIComponent(o.id)}&email=${encodeURIComponent(o.email)}" target="_blank">Track ↗</a></td><td>${escapeHtml(o.name)}<small>${escapeHtml(o.email)} · ${escapeHtml(o.phone)}</small><small>${escapeHtml(o.address)}</small></td><td>${escapeHtml(o.productTitle)} × ${o.quantity}</td><td>₹${Number(o.total).toLocaleString('en-IN')}</td><td><form method="post" action="/admin/orders/status" class="inline-form"><input type="hidden" name="orderId" value="${escapeHtml(o.id)}"><select name="status">${['New','Contacted','Confirmed','Shipped','Completed','Cancelled'].map(st=>`<option ${o.status===st?'selected':''}>${st}</option>`).join('')}</select><button class="small-btn">Update</button></form></td><td><form method="post" action="/admin/orders/delete" onsubmit="return confirm('Delete this order request?')"><input type="hidden" name="orderId" value="${escapeHtml(o.id)}"><button class="small-btn danger-btn">Delete</button></form></td></tr>`).join('')||'<tr><td colspan="6">No order requests yet.</td></tr>'}</tbody></table></div></section>`; const adminBody = body + ordersSection;
  res.send(page('Admin panel',adminBody,user));
});
app.post('/admin/tags', requireAuth, requireAdmin, (req,res) => { let code=String(req.body.code||'').trim().toUpperCase().replace(/[^A-Z0-9_-]/g,'').slice(0,40); if(!code) code='TG'+crypto.randomBytes(3).toString('hex').toUpperCase(); if(db.tags.some(t=>t.code.toLowerCase()===code.toLowerCase())) return res.status(409).send(page('Duplicate tag',`<div class="not-found"><h1>Tag code already exists.</h1><a class="btn" href="/admin">Back to admin</a></div>`,currentUser(req))); const activationCode=makeActivationCode(); db.tags.push({id:id('TAG_'),code,userId:null,active:true,activationHash:hashActivationCode(activationCode),createdAt:new Date().toISOString()}); save(); req.session.newTagNotice={code,activationCode,url:`${req.protocol}://${req.get('host')}/t/${encodeURIComponent(code)}`}; res.redirect('/admin'); });
app.post('/admin/products', requireAuth, requireAdmin, upload.single('imageFile'), (req,res) => {
 const title=String(req.body.title||'').trim().slice(0,100), audience=String(req.body.audience||'').trim(), category=String(req.body.category||'').trim().slice(0,80), description=String(req.body.description||'').trim().slice(0,500), image=(req.file ? `/uploads/${req.file.filename}` : safeUrl(req.body.image)), url=safeUrl(req.body.url), details=String(req.body.details||'').trim().slice(0,180), price=Number(req.body.price);
 if(!title||!['Students','Creators','Professionals'].includes(audience)||!category||!description||!image||!Number.isFinite(price)||price<0||price>1000000) return res.status(400).send(page('Invalid product','<div class="not-found"><h1>Product details check karo.</h1><p class="muted">Name, audience, category, description, valid image URL aur price required hain.</p><a class="btn" href="/admin">Back to admin</a></div>',currentUser(req)));
 db.products.unshift({id:id('PRD_'),title,audience,category,price,description,image,url,details:details||'Curated pick'}); save(); res.redirect('/admin#products');
});
app.post('/admin/tags/toggle', requireAuth, requireAdmin, (req,res)=>{const t=db.tags.find(x=>x.code===String(req.body.code||'')); if(t){t.active=!t.active;save();}res.redirect('/admin');});

app.get('/products/:id', (req,res)=>{ const p=db.products.find(x=>x.id===req.params.id); if(!p) return res.status(404).send(page('Product not found','<div class="not-found"><h1>Product not found</h1><a class="btn" href="/products">Back to products</a></div>',currentUser(req))); const body=`<div class="product-detail"><a class="text-link" href="/products">← All products</a><div class="product-detail-grid"><div class="product-detail-image"><img src="${escapeHtml(p.image)}" alt="${escapeHtml(p.title)}"></div><section class="panel product-detail-copy"><div class="eyebrow">${escapeHtml(p.category)}</div><h1>${escapeHtml(p.title)}</h1><div class="product-detail-price">₹${Number(p.price).toLocaleString('en-IN')}</div><p>${escapeHtml(p.description)}</p><p class="muted">${escapeHtml(p.details||'')}</p><form class="form" method="post" action="/orders"><input type="hidden" name="productId" value="${escapeHtml(p.id)}"><h2>Order this product</h2><div class="two-col"><div><label>Full name</label><input name="name" required maxlength="80"></div><div><label>Phone number</label><input name="phone" required pattern="[0-9+() -]{8,18}" maxlength="18"></div></div><label>Email</label><input name="email" type="email" required><label>Delivery address</label><textarea name="address" required maxlength="500" rows="3"></textarea><label>Quantity</label><input name="quantity" type="number" min="1" max="20" value="1" required><button class="btn full" type="submit">Place order request · ₹${Number(p.price).toLocaleString('en-IN')}</button><p class="tiny-note">Payment is not collected online in this MVP. Tagnet will contact you to confirm.</p></form></section></div></div>`; res.send(page(p.title,body,currentUser(req))); });
app.get('/my-orders', requireAuth, (req,res)=>{const user=currentUser(req);if(user.isAdmin)return res.redirect('/admin#orders');const orders=db.orders.filter(o=>String(o.email||'').toLowerCase()===String(user.email||'').toLowerCase());const body=`<div class="page-heading"><div><div class="eyebrow">YOUR ACCOUNT</div><h1>My orders<span class="period">.</span></h1><p class="muted">Orders placed using your account email, with current status and order date.</p></div><a class="text-link" href="/products">Continue shopping →</a></div>${orders.length?`<div class="my-orders-list">${orders.map(o=>`<article class="my-order-card"><div class="my-order-head"><div><span class="eyebrow">${escapeHtml(o.id)}</span><h2>${escapeHtml(o.productTitle)}</h2><p class="muted">Ordered on ${new Date(o.createdAt).toLocaleString('en-IN')}</p></div><span class="status-pill">${escapeHtml(o.status)}</span></div><div class="my-order-meta"><span>Quantity <strong>${o.quantity}</strong></span><span>Unit price <strong>₹${Number(o.price).toLocaleString('en-IN')}</strong></span><span>Total <strong>₹${Number(o.total).toLocaleString('en-IN')}</strong></span></div><p class="muted">Delivery address: ${escapeHtml(o.address)}</p><a class="btn" href="/track-order?id=${encodeURIComponent(o.id)}&email=${encodeURIComponent(o.email)}">Track order →</a></article>`).join('')}</div>`:'<section class="panel empty-orders"><h2>No orders yet</h2><p class="muted">When you place an order using this account email, it will appear here.</p><a class="btn" href="/products">Browse products</a></section>'}`;res.send(page('My orders',body,user));});
app.post('/orders',(req,res)=>{const p=db.products.find(x=>x.id===String(req.body.productId||'')); if(!p)return res.status(404).send('Product not found');const quantity=Math.max(1,Math.min(20,Number.parseInt(req.body.quantity,10)||1));const order={id:'ORD-'+crypto.randomBytes(4).toString('hex').toUpperCase(),productId:p.id,productTitle:p.title,price:Number(p.price),quantity,total:Number(p.price)*quantity,name:String(req.body.name||'').trim().slice(0,80),phone:String(req.body.phone||'').trim().slice(0,18),email:String(req.body.email||'').trim().toLowerCase().slice(0,120),address:String(req.body.address||'').trim().slice(0,500),status:'New',statusHistory:[{status:'New',at:new Date().toISOString()}],createdAt:new Date().toISOString()};if(!order.name||!order.phone||!order.email||!order.address)return res.status(400).send('Please fill all required fields.');db.orders.unshift(order);save();res.redirect('/track-order?id='+encodeURIComponent(order.id)+'&email='+encodeURIComponent(order.email));});
app.get('/track-order',(req,res)=>{const body=`<section class="auth-wrap"><div class="eyebrow">ORDER UPDATES</div><h1>Track your order<span class="period">.</span></h1><p class="muted">Enter your order ID and the email used at checkout.</p><form class="form" method="get" action="/track-order"><label>Order ID</label><input name="id" required value="${escapeHtml(req.query.id||'')}" placeholder="ORD-XXXXXXXX"><label>Email</label><input name="email" type="email" required value="${escapeHtml(req.query.email||'')}"><button class="btn full" type="submit">Find my order</button></form>${req.query.id?(()=>{const o=db.orders.find(x=>x.id.toLowerCase()===String(req.query.id).toLowerCase()&&x.email.toLowerCase()===String(req.query.email||'').toLowerCase());return o?`<div class="order-track-card"><span class="status-pill">${escapeHtml(o.status)}</span><h2>${escapeHtml(o.productTitle)}</h2><p>Order <strong>${escapeHtml(o.id)}</strong></p><p>${o.quantity} × ₹${o.price.toLocaleString('en-IN')} · <strong>₹${o.total.toLocaleString('en-IN')}</strong></p><p class="muted">Last updated: ${new Date(o.updatedAt||o.createdAt).toLocaleString('en-IN')}</p><div class="order-history">${(Array.isArray(o.statusHistory)&&o.statusHistory.length?o.statusHistory:[{status:o.status,at:o.updatedAt||o.createdAt}]).map(h=>`<div><strong>${escapeHtml(h.status)}</strong><span>${new Date(h.at).toLocaleString('en-IN')}</span></div>`).join('')}</div><div class="tracking-steps">${['New','Contacted','Confirmed','Shipped','Completed'].map((st,i)=>`<span class="${['Cancelled'].includes(o.status)?'':(['New','Contacted','Confirmed','Shipped','Completed'].indexOf(o.status)>=i?'done':'')} ">${st}</span>`).join('')}</div>${o.status==='Cancelled'?'<p class="error">This order was cancelled. Contact Tagnet if you need help.</p>':''}</div>`:'<p class="error">Order not found. Check the ID and email.</p>';})():''}</section>`;res.send(page('Track order',body,currentUser(req)));});
app.post('/admin/orders/status',requireAuth,requireAdmin,(req,res)=>{const o=db.orders.find(x=>x.id===String(req.body.orderId||''));if(o&&['New','Contacted','Confirmed','Shipped','Completed','Cancelled'].includes(req.body.status)){o.status=req.body.status;o.updatedAt=new Date().toISOString();if(!Array.isArray(o.statusHistory))o.statusHistory=[];o.statusHistory.push({status:o.status,at:o.updatedAt});save();}res.redirect('/admin#orders');});
app.post('/admin/orders/delete',requireAuth,requireAdmin,(req,res)=>{db.orders=db.orders.filter(o=>o.id!==String(req.body.orderId||''));save();res.redirect('/admin#orders');});
app.post('/admin/users/delete',requireAuth,requireAdmin,(req,res)=>{const uid=String(req.body.userId||'');if(!uid||db.users.some(u=>u.id===uid&&u.isAdmin))return res.redirect('/admin');const profile=db.profiles.find(p=>p.userId===uid);if(profile&&profile.avatar&&profile.avatar.startsWith('/uploads/')){const f=path.join(UPLOAD_DIR,path.basename(profile.avatar));try{if(fs.existsSync(f))fs.unlinkSync(f)}catch{}}db.users=db.users.filter(u=>u.id!==uid);db.profiles=db.profiles.filter(p=>p.userId!==uid);db.tags=db.tags.map(t=>t.userId===uid?{...t,userId:null}:t);db.profileViews=db.profileViews.filter(v=>!profile||v.username!==profile.username);save();res.redirect('/admin');});
app.get('/admin/tag-lookup',(req,res)=>{const code=String(req.query.code||'').trim().toUpperCase();const t=db.tags.find(x=>x.code===code);const p=t&&t.userId?profileFor(t.userId):null;const c=t&&t.userId?db.users.find(u=>u.id===t.userId):null;const body=`<section class="panel"><h2>NFC tag lookup</h2><form class="filter-form"><label>Tag ID<input name="code" value="${escapeHtml(code)}" placeholder="TG123ABC" required></label><button class="btn">Look up tag</button></form>${code?(t?`<div class="tag-lookup-result"><h3>${escapeHtml(t.code)}</h3><p>Status: <strong>${t.active?'Active':'Disabled'}</strong> · Assigned: <strong>${p?'Yes':'No'}</strong></p><p>Activation code: <strong>Hashed / not recoverable</strong></p><label>NFC URL to write to chip</label><input readonly value="${escapeHtml(`${req.protocol}://${req.get('host')}/t/${encodeURIComponent(t.code)}`)}"><p>Customer: ${c?escapeHtml(c.email):'Unassigned'}</p>${p?`<p>Name: ${escapeHtml(p.name)} · Username: @${escapeHtml(p.username)}</p><a href="/u/${encodeURIComponent(p.username)}" target="_blank">Open profile ↗</a>`:''}</div>`:'<p class="error">No tag found with that ID.</p>') : ''}</section>`;res.send(page('NFC tag lookup',body,currentUser(req)));});

